from thelmic.live_channel import LiveChannel
ch = LiveChannel(lower_priority=False); ch.start()
try:
    # find URIs we need from the audio_effects browser root
    res = ch.get_browser_items_at_path('audio_effects').result(timeout=10)
    wanted = {'Glue Compressor': None, 'Saturator': None, 'EQ Eight': None, 'Compressor': None}
    for it in res['items']:
        if it['name'] in wanted and it['uri']:
            wanted[it['name']] = it['uri']
    print('found URIs:')
    for k, v in wanted.items():
        print(f'  {k}: {v}')
finally:
    ch.stop()
" 2>&1
